const b = $input.first().json.body || {};
const escapeHtml = value => String(value).replace(/[&<>"']/g, character => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' })[character]);
if (b.event !== 'mfa.login.code') throw new Error('Evento no permitido');
if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(String(b.email || ''))) throw new Error('Correo inválido');
if (!/^\d{6}$/.test(String(b.token_mfa || ''))) throw new Error('Código inválido');
if (!Number.isInteger(b.expires_in_seconds) || b.expires_in_seconds < 60 || b.expires_in_seconds > 300) throw new Error('Vigencia inválida');
if (typeof b.timestamp !== 'string' || !Number.isFinite(Date.parse(b.timestamp))) throw new Error('Fecha inválida');
const minutes = Math.ceil(b.expires_in_seconds / 60);
const code = escapeHtml(b.token_mfa);
const html = `<div style="font-family:Arial,sans-serif;max-width:420px;margin:auto;padding:24px;border:1px solid #e2e8f0;border-radius:12px"><h2 style="margin:0 0 8px;color:#0f172a">Código de verificación</h2><p style="color:#475569">Usa este código para completar tu inicio de sesión. Vence en ${minutes} minutos.</p><p style="font-size:34px;letter-spacing:8px;font-weight:700;text-align:center;margin:24px 0;color:#0d4f9c">${code}</p><p style="color:#64748b;font-size:13px">Si no fuiste tú, ignora este mensaje. Nunca compartas este código.</p></div>`;
return [{ json: { to: b.email, subject: 'Tu código de verificación', html } }];
